/// Replaces every negative element in `a` with 0, in place.
/// Non-negative elements are left unchanged. The vector length is unchanged.
pub fn zap_negatives(a: &mut Vec<i32>) {
    for x in a.iter_mut() {
        if *x < 0 {
            *x = 0;
        }
    }
}

